    def filter_members(self, members: ObjectMembers, want_all: bool) -> List[ObjectMember]:
        """Filter the given member list.

        *members* is either a list of tuples or a list of :class:`ObjectMember`\\ s.

        *want_all* is true if the user wants to document all members.

        Returns a list of :class:`ObjectMember`\\ s that are actually to be
        documented.
        """
        members = [m if isinstance(m, ObjectMember) else ObjectMember(*m)
                   for m in members]
        ret = []

        # search for members in source code too
        namespace = '.'.join(self.objpath)
        if self.analyzer:
            attr_docs = self.analyzer.find_attr_docs()
        else:
            attr_docs = {}

        # remove members given by exclude-members
        if self.options.exclude_members:
            members = [m for m in members if m.__name__ not in self.options.exclude_members]

        # as a special case, if we have a module without __all__ set, we want
        # to include all members, even if they are not imported
        if want_all and self.objtype == 'module' and \
           not getattr(self.object, '__all__', None):
            want_all = False

        # remove non-documented members if want_all is false
        if not want_all:
            members = [m for m in members if m.__name__ in self.options.members]

        # document members with the given docstring if :members: is given
        if self.options.members is ALL:
            for m in members:
                if m.__name__ in attr_docs:
                    m.docstring = '\n'.join(attr_docs[m.__name__])
        else:
            for name in self.options.members:
                if name in attr_docs:
                    m = ObjectMember(name, INSTANCEATTR, '\n'.join(attr_docs[name]))
                    members.append(m)

        # remove members from __all__ if want_all is false
        if want_all and self.objtype == 'module':
            if getattr(self.object, '__all__', None):
                all_members = set(self.object.__all__)
                members = [m for m in members if m.__name__ in all_members]

        # remove special members
        if not self.options.special_members:
            members = [m for m in members if not special_member_re.match(m.__name__)]

        # remove private members unless explicitly given
        if not self.options.private_members:
            members = [m for m in members if not m.__name__.startswith('_')]

        # remove members that are not documented
        for m in members:
            if m.skipped:
                continue
            ret.append(m)

        return ret
